/* AVL Control v3 — protótipo vanilla, sem dependências externas.
 * Domínio -> repositório local -> seletores -> componentes HTML -> eventos.
 * Na migração React, preservar Domain/Repo/selectors e substituir a camada de UI.
 * Valores monetários armazenados em centavos; datas civis em YYYY-MM-DD.
 * Perfis são perspectivas demonstrativas da mesma frota, não autorização real.
 */
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => (Number(n || 0) / 100).toLocaleString('pt-BR', {style:'currency',currency:'BRL'});
const num = n => Number(n || 0).toLocaleString('pt-BR', {maximumFractionDigits:1});
const today = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const monthDate = (offset,day=10) => {const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate())).padStart(2,'0')}`;};
const addMonths = (s,n) => {const [y,m,d]=s.split('-').map(Number);const t=new Date(y,m-1+n,1);return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(Math.min(d,new Date(t.getFullYear(),t.getMonth()+1,0).getDate())).padStart(2,'0')}`;};
const dateLabel = s => s ? s.split('-').reverse().join('/') : '—';
const uid = () => crypto.randomUUID ? crypto.randomUUID() : `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const sum = (arr,key) => arr.reduce((a,x)=>a+Number(x[key] || 0),0);
const cents = value => Math.round(Number(value)*100);
function assert(ok,msg){if(!ok)throw new Error(msg);}
function seedData(){
 const vehicles=[
 {id:'v1',plate:'ABC-8899',model:'Volvo FMX 500 Basculante',category:'Caminhão',year:2022,meter:68400,unit:'km',lastOil:60000,oilInterval:10000,monthly:1250000,status:'Disponível',clientId:'c1',photos:[],tank:300},
 {id:'v2',plate:'KRH-4120',model:'Caterpillar 426F2',category:'Maquinário',year:2021,meter:3200,unit:'h',lastOil:2800,oilInterval:500,monthly:980000,status:'Disponível',clientId:'c1',photos:[],tank:160},
 {id:'v3',plate:'GXX-9011',model:'Toyota Hilux CD 4x4',category:'Pickup',year:2023,meter:42100,unit:'km',lastOil:40000,oilInterval:10000,monthly:540000,status:'Disponível',clientId:'',photos:[],tank:80},
 {id:'v4',plate:'RST-5A12',model:'Mercedes-Benz Atego 2730',category:'Caminhão',year:2020,meter:112000,unit:'km',lastOil:101000,oilInterval:10000,monthly:1100000,status:'Manutenção',clientId:'c2',photos:[],tank:300}
 ];
 const invoices=[];
 for(let m=-5;m<=0;m++)for(let i=0;i<3;i++){
  const amount=[1250000,980000,1100000][i]+(m+5)*12000;
  invoices.push({id:`i${m}-${i}`,vehicleId:['v1','v2','v4'][i],clientId:i===2?'c2':'c1',role:'locador',issued:monthDate(m,1),due:monthDate(m,i===0?5:20),amount,description:`Locação mensal · ${monthDate(m,1).slice(0,7)}`,payments:m<0?[{id:uid(),date:monthDate(m,20),amount}]:[],installment:'1/1'});
 }
 const expenses=[];
 for(let m=-5;m<=0;m++)for(const role of ['locador','locatario'])for(let i=0;i<4;i++)expenses.push({id:uid(),role,vehicleId:`v${i+1}`,clientId:i===3?'c2':i<2?'c1':'',category:['Combustível','Manutenção','Pedágio','Peças / Insumos'][i],amount:[148000,92000,18500,77000][i]+(m+5)*1200,date:monthDate(m,8),liters:i===0?240:0,description:'Lançamento demonstrativo',workId:i<2?'w1':'w2'});
 return {version:3,vehicles,clients:[{id:'c1',name:'Construtora Horizonte',document:'',contact:'financeiro@horizonte.exemplo'},{id:'c2',name:'Infraestrutura Sul',document:'',contact:'contato@infrasul.exemplo'}],works:[{id:'w1',name:'Edifício Horizon Lux',location:'São Paulo · SP',manager:'Eng. Ricardo Alves',status:'Ativa'},{id:'w2',name:'Rodovia BR-101 · Trecho Sul',location:'Santos · SP',manager:'Eng. Mariana Costa',status:'Ativa'},{id:'w3',name:'Parque Eólico Serra Verde',location:'Caetité · BA',manager:'Carlos Mendes',status:'Em início'}],drivers:[{id:'d1',name:'João Silva',license:'E',expires:'2027-11-15',workId:'w1',phone:'(11) 98765-4321'},{id:'d2',name:'Marcos Oliveira',license:'D',expires:'2027-10-05',workId:'w2',phone:'(13) 99123-8877'}],trips:[{id:'t1',vehicleId:'v1',workId:'w1',driverId:'d1',start:monthDate(0,1),startMeter:68000,startFuel:180,end:null},{id:'t2',vehicleId:'v2',workId:'w2',driverId:'d2',start:monthDate(0,1),startMeter:3150,startFuel:90,end:null}],checklists:[],expenses,invoices,categories:['Combustível','Manutenção','Pedágio','Peças / Insumos','Seguro / Taxas'],maintenance:[{id:'m1',vehicleId:'v4',type:'Corretiva',description:'Substituição da embreagem e alinhamento.',date:monthDate(0,10),status:'Em andamento',cost:320000,oil:false}],documents:[{id:'doc1',vehicleId:'v1',type:'Entrega na obra',date:monthDate(0,1),notes:'Recebido sem ressalvas.',name:'',data:'',status:'Registrado'}],regulations:[{id:'reg1',vehicleId:'v4',title:'Licenciamento',due:monthDate(-1,10)},{id:'reg2',vehicleId:'v1',title:'Seguro da frota',due:monthDate(1,20)}]};
}
const STORAGE='avl-control-v3';
let loadWarning='';
const Repo={
 load(){try{const raw=localStorage.getItem(STORAGE);if(raw){const data=JSON.parse(raw);if(data.version===3&&Array.isArray(data.vehicles)&&Array.isArray(data.invoices)&&Array.isArray(data.checklists))return data;throw Error('Versão incompatível');}}catch(e){loadWarning='Não foi possível recuperar os dados locais. A demonstração foi aberta; exporte um backup antes de continuar se necessário.';}return seedData();},
 save(next){localStorage.setItem(STORAGE,JSON.stringify(next));},
 transact(change){const next=structuredClone(db);change(next);try{this.save(next);}catch(e){throw Error('Não foi possível salvar no navegador. O armazenamento pode estar cheio ou bloqueado. Reduza os anexos e tente novamente. Nenhuma alteração foi aplicada.');}db=next;}
};
let db=Repo.load();
const ui={role:'locador',tab:'dashboard',vehicleId:null,status:'Todos',search:'',report:'vehicle',from:monthDate(-5,1),to:monthDate(0,31),vehicle:'all',category:'all',client:'all',work:'all',invoiceStatus:'all',financeTab:'receipts'};
let photosDraft=[],attachmentDraft=null,photoBusy=false,formGeneration=0;
const getVehicle = id => db.vehicles.find(v=>v.id===id);
const vehicleName=id=>getVehicle(id)?.plate || '—';
const clientName=id=>db.clients.find(c=>c.id===id)?.name || 'Sem cliente';
const workName=id=>db.works.find(w=>w.id===id)?.name || 'Pátio';
const driverName=id=>db.drivers.find(d=>d.id===id)?.name || '—';
const activeTrip=(id,data=db)=>data.trips.find(t=>t.vehicleId===id&&!t.end);
const pendingCheck=(id,data=db)=>data.checklists.find(c=>c.vehicleId===id&&!c.done);
const paid=i=>sum(i.payments,'amount');
const balance=i=>Math.max(0,i.amount-paid(i));
const invoiceStatus=i=>balance(i)===0?'Recebido':i.due<today()?'Vencido':paid(i)>0?'Parcial':'Em aberto';
const oil=v=>({left:v.lastOil+v.oilInterval-v.meter,next:v.lastOil+v.oilInterval});
function vehicleStatus(v){if(v.status!=='Disponível')return v.status;if(ui.role==='locador')return v.clientId?'Locado':'Disponível';return activeTrip(v.id)?'Em obra':'Disponível';}
function inRange(date){return date>=ui.from&&date<=ui.to;}
function selectedVehicles(){return db.vehicles.filter(v=>(ui.vehicle==='all'||v.id===ui.vehicle)&&(ui.client==='all'||v.clientId===ui.client||db.invoices.some(i=>i.vehicleId===v.id&&i.role===ui.role&&i.clientId===ui.client&&inRange(i.issued))||db.expenses.some(e=>e.vehicleId===v.id&&e.role===ui.role&&e.clientId===ui.client&&inRange(e.date)))&&(ui.work==='all'||db.trips.some(t=>t.vehicleId===v.id&&t.workId===ui.work&&t.start<=ui.to&&(!t.end||t.end>=ui.from))));}
function selectedExpenses(){return db.expenses.filter(e=>e.role===ui.role&&inRange(e.date)&&(ui.vehicle==='all'||e.vehicleId===ui.vehicle)&&(ui.category==='all'||e.category===ui.category)&&(ui.work==='all'||e.workId===ui.work)&&(ui.client==='all'||e.clientId===ui.client));}
function selectedInvoices(){return db.invoices.filter(i=>i.role===ui.role&&(ui.vehicle==='all'||i.vehicleId===ui.vehicle)&&(ui.client==='all'||i.clientId===ui.client)&&(ui.work==='all'||i.workId===ui.work)&&(ui.invoiceStatus==='all'||invoiceStatus(i)===ui.invoiceStatus));}
function metrics(){const invoices=selectedInvoices();return {billed:sum(invoices.filter(i=>inRange(i.issued)),'amount'),received:invoices.reduce((s,i)=>s+sum(i.payments.filter(p=>inRange(p.date)),'amount'),0),expense:sum(selectedExpenses(),'amount'),due:invoices.filter(i=>inRange(i.due)).reduce((s,i)=>s+balance(i),0),overdue:invoices.filter(i=>inRange(i.due)&&invoiceStatus(i)==='Vencido').reduce((s,i)=>s+balance(i),0)};}
const Domain={
 allocate(data,id,input){const v=data.vehicles.find(v=>v.id===id);assert(v&&v.status==='Disponível'&&!activeTrip(id,data),'O veículo não está disponível.');assert(!pendingCheck(id,data),'Conclua o checklist pendente antes de uma nova saída.');assert(data.works.some(w=>w.id===input.workId&&w.status!=='Concluída'),'Selecione uma obra ativa.');assert(data.drivers.some(d=>d.id===input.driverId),'Selecione um motorista.');assert(input.start<=today(),'A saída não pode estar no futuro.');assert(input.startMeter>=v.meter,'A leitura de saída não pode ser menor que a atual.');assert(input.startFuel>=0&&input.startFuel<=v.tank,'O combustível deve estar entre zero e a capacidade do tanque.');v.meter=input.startMeter;data.trips.push({id:uid(),vehicleId:id,...input,end:null});},
 returnTrip(data,id,input){const t=data.trips.find(t=>t.vehicleId===id&&!t.end);const v=data.vehicles.find(v=>v.id===id);assert(t&&v,'Não existe uma alocação aberta.');assert(input.end>=t.start&&input.end<=today(),'Informe um retorno entre a saída e hoje.');assert(input.endMeter>=Math.max(t.startMeter,v.meter),'A leitura de retorno não pode diminuir.');t.end=input.end;t.endMeter=input.endMeter;v.meter=input.endMeter;data.checklists.push({id:uid(),vehicleId:id,tripId:t.id,date:input.end,done:false});},
 checklist(data,id,input){const c=data.checklists.find(c=>c.id===id);assert(c&&!c.done,'Checklist já concluído ou inexistente.');const t=data.trips.find(t=>t.id===c.tripId);const v=data.vehicles.find(v=>v.id===c.vehicleId);assert(input.endFuel>=0&&input.endFuel<=v.tank&&input.refueled>=0,'Revise o combustível informado.');const consumed=t.startFuel+input.refueled-input.endFuel;assert(consumed>=0,'O combustível final supera o inicial mais os abastecimentos.');assert(input.confirmed,'Confirme a conferência das leituras e do combustível.');assert(['tires','brakes','lights','body','fluids'].every(k=>['Ok','Avaria'].includes(input[k])),'Preencha todos os itens de integridade.');const damage=['tires','brakes','lights','body','fluids'].some(k=>input[k]==='Avaria');assert(!damage||input.notes.trim().length>=5,'Descreva a avaria encontrada.');Object.assign(c,input,{done:true,completed:today(),consumed,distance:t.endMeter-t.startMeter,damage});if(damage){v.status='Necessita manutenção';data.maintenance.push({id:uid(),vehicleId:v.id,type:'Corretiva',description:`Avaria no retorno: ${input.notes}`,date:today(),status:'Pendente',cost:0,oil:false,checklistId:c.id});}},
 payment(data,id,input){const i=data.invoices.find(i=>i.id===id);assert(i,'Parcela não encontrada.');assert(Number.isInteger(input.amount)&&input.amount>0&&input.amount<=balance(i),'O recebimento deve ser maior que zero e não ultrapassar o saldo.');assert(input.date>=i.issued&&input.date<=today(),'A baixa deve ser entre a emissão e hoje.');i.payments.push({id:uid(),...input});},
 finishMaintenance(data,id,input){const m=data.maintenance.find(m=>m.id===id);assert(m&&m.status!=='Concluída','Serviço já concluído.');const v=data.vehicles.find(v=>v.id===m.vehicleId);assert(input.date>=m.date&&input.date<=today(),'A conclusão deve ocorrer entre a data do serviço e hoje.');assert(input.meter>=v.meter,'A leitura não pode diminuir.');m.status='Concluída';m.finished=input.date;m.cost=input.cost;m.oil=input.oil;v.meter=input.meter;if(input.oil)v.lastOil=input.meter;if(!data.maintenance.some(x=>x.vehicleId===v.id&&['Pendente','Em andamento'].includes(x.status)))v.status='Disponível';}
};
const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',veiculos:'M3 6h12v11H3z M15 10h4l3 4v3h-7 M7 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M18 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4',obras:'M4 21V5h10v16 M14 10h6v11 M7 8h4 M7 12h4 M7 16h4 M2 21h20',financeiro:'M3 5h18v14H3z M3 9h18 M16 15h2',manutencao:'m14 6 4 4 4-4a7 7 0 0 1-9 9L6 22l-4-4 7-7A7 7 0 0 1 18 2z',documentos:'M6 2h8l4 4v16H6z M14 2v5h5 M9 12h6 M9 16h6',relatorios:'M3 3v18h18 M7 16v-4 M12 16V8 M17 16V5',arrow:'m7 17 10-10 M7 7h10v10',check:'m5 12 4 4L19 6'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.veiculos}"/></svg>`;
const truck=()=>`<svg class="truck-art" viewBox="0 0 180 100" fill="none" aria-hidden="true"><path d="M15 22h100v47H15z M115 38h26l25 24v15h-51 M20 77h140 M135 43v19h25" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><path d="M24 29h82v30H24z" fill="currentColor" opacity=".15"/><circle cx="44" cy="78" r="11" fill="currentColor"/><circle cx="137" cy="78" r="11" fill="currentColor"/><circle cx="44" cy="78" r="4" fill="#ecf1f5"/><circle cx="137" cy="78" r="4" fill="#ecf1f5"/></svg>`;
const btn=(text,action,id='',style='')=>`<button type="button" class="btn ${style}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const badge=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
const statusBadge=s=>badge(s,['Recebido','Disponível','Concluída','Ok'].includes(s)?'green':['Vencido','Necessita manutenção','Avaria'].includes(s)?'red':'amber');
const empty=(text='Nenhum registro neste período.')=>`<div class="empty"><strong>Nada por aqui ainda</strong>${esc(text)}</div>`;
const head=(title,subtitle,actions='')=>`<div class="page-head"><div><span class="eyebrow muted">${ui.role==='locador'?'MINHA FROTA / MEUS RESULTADOS':'MINHAS OBRAS / MINHA OPERAÇÃO'}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;
const panel=(title,sub,body,action='')=>`<section class="panel"><div class="panel-head"><div><h3>${title}</h3><p>${sub}</p></div>${action}</div>${body}</section>`;
const metric=(title,value,note,kind='dashboard',color='')=>`<div class="metric ${color}"><div class="metric-top">${title}<span class="metric-icon">${icon(kind,17)}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${note}</div></div>`;
const opt=(id,label,current)=>`<option value="${esc(id)}" ${String(id)===String(current)?'selected':''}>${esc(label)}</option>`;
const select=(name,label,options,current='')=>`<label>${label}<select name="${name}" required>${options.map(x=>opt(x[0],x[1],current)).join('')}</select></label>`;
const field=(name,label,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs} required></label>`;
const form=(id,body,submit='Salvar')=>`<form id="${id}"><div class="error" id="form-error" hidden role="alert"></div>${body}<div class="form-actions">${btn('Cancelar','close-dialog')}<button class="btn primary" type="submit">${submit}</button></div></form>`;
function photo(v,cls=''){return `<div class="vehicle-photo ${cls}">${v.photos[0]?`<img src="${esc(v.photos[0])}" alt="${esc(v.model)}">`:`${truck()}<span class="no-photo">SEM FOTO</span>`}</div>`;}
function table(headers,rows,numeric=[]){if(!rows.length)return empty();return `<div class="table-wrap"><table><thead><tr>${headers.map((h,i)=>`<th class="${numeric.includes(i)?'numeric':''}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((c,i)=>`<td class="${numeric.includes(i)?'numeric':''}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function filters(advanced=false){return `<form id="filters" class="filters">${field('from','De',ui.from,'date')}${field('to','Até',ui.to,'date')}${advanced?`${select('vehicle','Veículo',[['all','Todos os veículos'],...db.vehicles.map(v=>[v.id,v.plate])],ui.vehicle)}${select('category','Categoria de despesa',[['all','Todas as categorias'],...db.categories.map(c=>[c,c])],ui.category)}${ui.role==='locador'?select('client','Cliente',[['all','Todos os clientes'],...db.clients.map(c=>[c.id,c.name])],ui.client):select('work','Obra',[['all','Todas as obras'],...db.works.map(w=>[w.id,w.name])],ui.work)}`:''}<button type="submit" class="btn primary">Aplicar</button>${btn('Limpar','clear-filters','','small')}<div class="filter-note">${advanced?'Categoria filtra despesas; receitas continuam integrais. ':''}Faturamento por emissão · recebimentos por data da baixa · saldos por vencimento.</div></form>`;}
function financialRows(){const expenses=selectedExpenses(),invoices=selectedInvoices();return selectedVehicles().map(v=>{const billed=sum(invoices.filter(i=>i.vehicleId===v.id&&inRange(i.issued)),'amount');const expense=sum(expenses.filter(e=>e.vehicleId===v.id),'amount');return {id:v.id,label:v.plate,billed,expense,result:billed-expense};});}
function categoryRows(){return db.categories.map(c=>({label:c,value:sum(selectedExpenses().filter(e=>e.category===c),'amount')})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value);}
function monthlyRows(){const result=[];let date=ui.from.slice(0,7)+'-01';let count=0;const invoices=selectedInvoices();while(date<=ui.to&&count++<120){const month=date.slice(0,7);result.push({label:month,value:sum(invoices.filter(i=>i.issued.startsWith(month)&&inRange(i.issued)),'amount')});date=addMonths(date,1);}return result;}
function barChart(rows){if(!rows.length)return empty();const max=Math.max(...rows.map(x=>x.value),1);return `<div class="bar-list">${rows.map((r,i)=>`<div><div class="bar-label"><span>${esc(r.label)}</span><strong>${money(r.value)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${r.value/max*100}%;background:${['#087e67','#2667cf','#71a7bb','#9ab4c4'][i%4]}"></div></div></div>`).join('')}</div>`;}
function vehicleChart(rows){if(!rows.length)return empty();const width=Math.max(460,rows.length*90),height=220,max=Math.max(...rows.flatMap(x=>[x.billed,x.expense]),1),gap=(width-60)/rows.length;return `<div class="table-wrap"><svg class="chart" style="min-width:${width}px" viewBox="0 0 ${width} ${height}" role="img" aria-label="Comparação de faturamento e despesas por veículo">${[0,1,2,3].map(i=>`<line x1="40" y1="${25+i*48}" x2="${width}" y2="${25+i*48}" stroke="#edf1f4"/><text x="0" y="${29+i*48}">${num(max*(3-i)/3/100000)}k</text>`).join('')}${rows.map((r,i)=>{const x=50+i*gap,h1=r.billed/max*144,h2=r.expense/max*144;return `<rect x="${x}" y="${169-h1}" width="${Math.min(22,gap*.22)}" height="${h1}" rx="3" fill="#2667cf"><title>${esc(r.label)}: faturado ${money(r.billed)}</title></rect><rect x="${x+Math.min(27,gap*.27)}" y="${169-h2}" width="${Math.min(22,gap*.22)}" height="${h2}" rx="3" fill="#087e67"><title>Gastos ${money(r.expense)}</title></rect><text x="${x}" y="198">${esc(r.label)}</text>`;}).join('')}</svg></div><div class="legend"><span>Faturado</span><span>Gastos</span></div>`;}
function lineChart(rows){if(!rows.length)return empty();const max=Math.max(...rows.map(r=>r.value),1),w=Math.max(460,rows.length*65);const points=rows.map((r,i)=>`${45+i*(w-75)/Math.max(rows.length-1,1)},${165-r.value/max*130}`).join(' ');const first=rows[0].value,last=rows.at(-1).value,change=first?((last-first)/first*100).toFixed(1):null;return `<div class="trend-caption"><strong>${money(sum(rows,'value'))}</strong><span>${rows.length<2?'Selecione mais meses para comparar':change===null?'Sem base inicial para variação':`${Number(change)>=0?'+':''}${change}% entre o primeiro e o último mês`}</span></div><div class="table-wrap"><svg class="chart" style="min-width:${w}px" viewBox="0 0 ${w} 205" role="img" aria-label="Evolução do faturamento mensal">${[35,100,165].map(y=>`<line x1="40" y1="${y}" x2="${w-10}" y2="${y}" stroke="#e8edf1"/>`).join('')}<polyline points="45,165 ${points} ${45+(rows.length-1)*(w-75)/Math.max(rows.length-1,1)},165" fill="#eaf5f0"/><polyline points="${points}" fill="none" stroke="#087e67" stroke-width="3"/>${rows.map((r,i)=>`<circle cx="${45+i*(w-75)/Math.max(rows.length-1,1)}" cy="${165-r.value/max*130}" r="4" fill="#087e67"><title>${r.label}: ${money(r.value)}</title></circle><text x="${45+i*(w-75)/Math.max(rows.length-1,1)}" y="194" text-anchor="middle">${r.label.slice(5)}/${r.label.slice(2,4)}</text>`).join('')}</svg></div>`;}
function oilRows(){return selectedVehicles().sort((a,b)=>oil(a).left-oil(b).left);}
function oilList(){return oilRows().map(v=>{const o=oil(v),warn=o.left<=v.oilInterval*.15;return `<div class="oil-row"><div><strong>${esc(v.plate)} · ${esc(v.model)}</strong><p>Próxima troca: ${num(o.next)} ${v.unit}</p></div>${badge(o.left<0?`${num(-o.left)} ${v.unit} em atraso`:o.left===0?'Troca agora':`${num(o.left)} ${v.unit} restantes`,o.left<=0?'red':warn?'amber':'green')}</div>`;}).join('')||empty();}
function renderDashboard(){const m=metrics(),loc=ui.role==='locador',available=db.vehicles.filter(v=>vehicleStatus(v)==='Disponível'),pending=db.checklists.filter(c=>!c.done);return head('Painel da operação',loc?'O desempenho da sua frota, de ponta a ponta.':'Cada veículo no lugar certo. Cada retorno acompanhado.',btn('Abrir relatórios','nav','relatorios'))+`<section class="welcome"><div><span class="eyebrow">${loc?'RESULTADOS QUE MOVEM SUA FROTA':'CONTROLE QUE ACOMPANHA SUA OBRA'}</span><h2>${loc?'Uma visão clara do seu negócio.':'Sua operação, sob controle.'}</h2><p>${loc?'Acompanhe faturamento, custos e o próximo recebimento.':'Disponibilidade, checklists e manutenção em um só lugar.'}</p></div><div class="welcome-art">${truck()}</div></section>`+filters()+`<div class="metric-grid">${loc?metric('Faturamento',money(m.billed),'Emissões no período','financeiro'):metric('Veículos disponíveis',available.length,'Situação atual · consultar frota','veiculos')}${loc?metric('Recebido',money(m.received),'Baixas no período','financeiro','good'):metric('Checklists pendentes',pending.length,'Retornos aguardando conferência','documentos','warn')}${metric('Despesas',money(m.expense),'Lançamentos no período','financeiro')}${loc?metric('Saldo vencido',money(m.overdue),'Vencimentos no período','financeiro','warn'):metric('Trocas de óleo vencidas',db.vehicles.filter(v=>oil(v).left<=0).length,'Situação atual dos medidores','manutencao','warn')}</div><div class="grid-2">${panel('Faturamento × gastos por veículo','Valores no período selecionado',vehicleChart(financialRows()),btn('Detalhar','report','vehicle','small'))}${loc?panel('Faturamento mensal','Selecione um intervalo maior para comparar meses',lineChart(monthlyRows()),btn('6 meses','six-months','','small')):panel('Prontos para a próxima obra','Disponibilidade atual da frota',available.map(v=>`<div class="oil-row"><div><strong>${esc(v.plate)}</strong><p>${esc(v.model)}</p></div>${btn(pendingCheck(v.id)?'Checklist':'Alocar',pendingCheck(v.id)?'checklist':'allocate',pendingCheck(v.id)?.id||v.id,'small')}</div>`).join('')||empty())}</div><div class="grid-2">${panel('Onde estão os maiores gastos?','Despesas agrupadas por categoria',barChart(categoryRows()),btn('Detalhar','report','category','small'))}${panel('Troca de óleo','Leitura atual × intervalo de manutenção',oilList(),btn('Detalhar','report','oil','small'))}</div>${!loc?panel('Checklists de retorno','Conferência de combustível e integridade',pending.map(c=>`<div class="oil-row"><div><strong>${esc(vehicleName(c.vehicleId))}</strong><p>Retorno em ${dateLabel(c.date)}</p></div>${btn('Preencher','checklist',c.id,'small')}</div>`).join('')||empty('Todos os retornos foram conferidos.')):''}`;}
function renderVehicles(){const statuses=ui.role==='locador'?['Todos','Locado','Disponível','Manutenção','Necessita manutenção']:['Todos','Em obra','Disponível','Manutenção','Necessita manutenção','Checklist pendente'];const list=db.vehicles.filter(v=>(ui.status==='Todos'||(ui.status==='Checklist pendente'?pendingCheck(v.id):vehicleStatus(v)===ui.status))&&`${v.plate} ${v.model}`.toLowerCase().includes(ui.search.toLowerCase()));return head('Veículos',ui.role==='locador'?'Acompanhe a disponibilidade e o resultado de cada ativo.':'Organize saídas, retornos e a alocação nos canteiros.',btn('+ Cadastrar veículo','edit-vehicle','','primary'))+`<form id="search-form" class="filters"><label>Buscar por placa ou modelo<input name="search" value="${esc(ui.search)}" placeholder="Ex.: Volvo ou ABC-8899"></label><button class="btn" type="submit">Buscar</button></form><div class="chips">${statuses.map(s=>`<button class="chip ${ui.status===s?'active':''}" data-action="vehicle-filter" data-id="${s}">${s}</button>`).join('')}</div><div class="vehicle-grid">${list.map(v=>{const t=activeTrip(v.id),c=pendingCheck(v.id);return `<article class="vehicle-card"><button class="vehicle-photo" data-action="detail" data-id="${v.id}" aria-label="Ver detalhes de ${esc(v.plate)}">${v.photos[0]?`<img src="${esc(v.photos[0])}" alt="${esc(v.model)}">`:truck()+`<span class="no-photo">ADICIONE UMA FOTO</span>`}${statusBadge(vehicleStatus(v))}</button><div class="vehicle-body"><span class="plate">${esc(v.plate)} · ${esc(v.category)}</span><button class="vehicle-title" data-action="detail" data-id="${v.id}">${esc(v.model)}</button><div class="vehicle-facts"><div><small>Leitura atual</small><strong>${num(v.meter)} ${v.unit}</strong></div><div><small>${ui.role==='locador'?'Cliente':'Alocação'}</small><strong>${esc(ui.role==='locador'?clientName(v.clientId):t?workName(t.workId):'Pátio / disponível')}</strong></div></div>${c?badge('Checklist pendente','amber'):oil(v).left<=0?badge('Troca de óleo vencida','red'):badge(`Óleo: ${num(oil(v).left)} ${v.unit} restantes`,'green')}<div class="actions">${btn('Detalhes','detail',v.id,'small')}${btn('Editar','edit-vehicle',v.id,'small')}${ui.role==='locatario'?(t?btn('Finalizar rotina','return',v.id,'primary small'):c?btn('Checklist','checklist',c.id,'primary small'):v.status==='Disponível'?btn('Alocar em obra','allocate',v.id,'primary small'):''):''}</div></div></article>`;}).join('')}</div>${list.length?'':empty('Tente outro filtro ou cadastre um veículo.')}`;}
function renderDetail(){const v=getVehicle(ui.vehicleId);if(!v)return empty('Veículo não encontrado.');const inv=selectedInvoices().filter(i=>i.vehicleId===v.id),ex=selectedExpenses().filter(e=>e.vehicleId===v.id),trips=db.trips.filter(t=>t.vehicleId===v.id&&t.end&&inRange(t.end));const billed=sum(inv.filter(i=>inRange(i.issued)),'amount'),expense=sum(ex,'amount');return head(esc(v.model),`${esc(v.plate)} · ${esc(v.category)} · ${v.year}`,btn('← Frota','nav','veiculos')+btn('Editar veículo','edit-vehicle',v.id,'primary'))+`<div class="detail-hero">${photo(v)}<div class="panel detail-data"><div><small>Status atual</small>${statusBadge(vehicleStatus(v))}</div><div><small>Cliente</small><strong>${esc(clientName(v.clientId))}</strong></div><div><small>Leitura atual</small><strong>${num(v.meter)} ${v.unit}</strong></div><div><small>Locação mensal de referência</small><strong>${money(v.monthly)}</strong></div><div><small>Última troca de óleo</small><strong>${num(v.lastOil)} ${v.unit}</strong></div><div><small>Próxima troca</small><strong>${num(oil(v).next)} ${v.unit}</strong></div><div><small>Saldo para a troca</small>${badge(`${num(oil(v).left)} ${v.unit}`,oil(v).left<=0?'red':'green')}</div></div></div>${v.photos.length>1?`<div class="gallery">${v.photos.map(src=>`<img src="${esc(src)}" alt="Foto de ${esc(v.model)}" width="140">`).join('')}</div>`:''}`+filters()+`<div class="metric-grid">${metric('Faturado no período',money(billed),'Por data de emissão','financeiro')}${metric('Gastos no período',money(expense),'Despesas registradas','financeiro')}${metric('Resultado',money(billed-expense),'Faturado menos despesas','relatorios','good')}${metric(v.unit==='km'?'KM rodados':'Horas trabalhadas',num(trips.reduce((s,t)=>s+t.endMeter-t.startMeter,0)),`Rotinas encerradas no período · ${v.unit}`,'veiculos')}</div>${panel('Histórico de manutenção','Serviços registrados para este veículo',maintenanceTable(db.maintenance.filter(m=>m.vehicleId===v.id)))}<div class="section-gap">${panel('Rotinas e checklists','Histórico preservado de cada saída e retorno',table(['Obra','Motorista','Saída','Retorno','Percurso','Checklist'],db.trips.filter(t=>t.vehicleId===v.id).map(t=>{const c=db.checklists.find(c=>c.tripId===t.id);return [esc(workName(t.workId)),esc(driverName(t.driverId)),dateLabel(t.start),dateLabel(t.end),t.end?`${num(t.endMeter-t.startMeter)} ${v.unit}`:'Em andamento',c?btn(c.done?'Ver conferência':'Preencher','checklist',c.id,'small'):'—'];})))}</div>`;}
function openVehicle(id){const v=getVehicle(id)||{plate:'',model:'',category:'Caminhão',year:new Date().getFullYear(),meter:0,unit:'km',lastOil:0,oilInterval:10000,monthly:0,status:'Disponível',clientId:'',photos:[],tank:300};photosDraft=[...v.photos];openDialog(id?'Editar veículo':'Um novo veículo para sua frota',form('vehicle-form',`<input type="hidden" name="id" value="${esc(id)}"><p class="hint">Identifique o veículo, configure a manutenção e adicione fotos. Campos com valores são obrigatórios.</p><fieldset><legend>01 · Identificação</legend><div class="form-grid">${field('model','Nome e modelo do veículo',v.model,'text','maxlength="100" placeholder="Ex.: Volvo FMX 500 Basculante"')}${field('plate','Placa ou identificação do equipamento',v.plate,'text','maxlength="20"')}${select('category','Categoria',[['Caminhão','Caminhão'],['Maquinário','Maquinário'],['Pickup','Pickup'],['Utilitário','Utilitário']],v.category)}${field('year','Ano de fabricação',v.year,'number','min="1950" max="2100"')}</div></fieldset><fieldset><legend>02 · Operação e manutenção</legend><div class="form-grid">${select('unit','Tipo de medidor',[['km','Quilômetros (km)'],['h','Horas (h)']],v.unit)}${field('meter','Leitura atual do medidor',v.meter,'number','min="0" step="0.1"')}${field('lastOil','Leitura na última troca de óleo',v.lastOil,'number','min="0" step="0.1"')}${field('oilInterval','Intervalo entre trocas (km ou h)',v.oilInterval,'number','min="1" step="0.1"')}${field('tank','Capacidade do tanque (litros)',v.tank,'number','min="1" step="0.1"')}${select('status','Condição do veículo',[['Disponível','Operacional'],['Manutenção','Em manutenção'],['Necessita manutenção','Necessita manutenção']],v.status)}</div><p class="hint">O alerta é calculado por última troca + intervalo − leitura atual. O status de locação e obra é derivado dos vínculos do veículo.</p></fieldset><fieldset><legend>03 · Dados da locação</legend><div class="form-grid">${field('monthly','Valor mensal de referência (R$)',v.monthly/100,'number','min="0" step="0.01"')}${ui.role==='locador'?select('clientId','Cliente atual',[['','Sem locação ativa'],...db.clients.map(c=>[c.id,c.name])],v.clientId):`<input name="clientId" type="hidden" value="${esc(v.clientId)}">`}</div><p class="hint">O valor de referência não gera faturamento automaticamente. Registre as parcelas no financeiro.</p></fieldset><fieldset><legend>04 · Fotos do veículo</legend><label class="upload">Adicionar até 4 imagens<input id="vehicle-images" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="hint">JPG, PNG ou WebP, até 8 MB cada. As fotos são reduzidas para o armazenamento local.</p><div id="photo-draft" class="gallery"></div></fieldset>`,'Salvar veículo'));const client=$('[name="clientId"]');if(client)client.required=false;renderPhotoDraft();}
function renderPhotoDraft(){$('#photo-draft').innerHTML=photosDraft.map((src,i)=>`<div class="gallery-item"><img src="${esc(src)}" alt="Foto ${i+1}"><button type="button" data-action="photo-main" data-id="${i}" class="${i===0?'primary-image':''}">${i===0?'✓ Principal':'Tornar principal'}</button><button type="button" data-action="photo-remove" data-id="${i}">Remover</button></div>`).join('');}
function openAllocation(id){const v=getVehicle(id);assert(ui.role==='locatario','Troque para a visão do locatário.');openDialog('Alocar veículo em obra',form('allocation-form',`<input name="id" type="hidden" value="${id}"><div class="notice">${esc(v.plate)} · ${esc(v.model)}</div><div class="form-grid">${select('workId','Obra de destino',db.works.filter(w=>w.status!=='Concluída').map(w=>[w.id,w.name]))}${select('driverId','Motorista responsável',db.drivers.map(d=>[d.id,d.name]))}${field('start','Data da saída',today(),'date',`max="${today()}"`)}${field('startMeter',`Leitura na saída (${v.unit})`,v.meter,'number',`min="${v.meter}" step="0.1"`)}${field('startFuel','Combustível no tanque na saída (L)',0,'number',`min="0" max="${v.tank}" step="0.1"`)}</div><p class="hint">A obra e o motorista ficam registrados no histórico desta rotina.</p>`,'Confirmar alocação'));}
function openReturn(id){const v=getVehicle(id),t=activeTrip(id);assert(t,'Não há rotina em andamento.');openDialog('Finalizar rotina e registrar retorno',form('return-form',`<input name="id" type="hidden" value="${id}"><div class="notice">${esc(v.plate)} · ${esc(workName(t.workId))}<br>Saída: ${num(t.startMeter)} ${v.unit} · ${dateLabel(t.start)}</div><div class="form-grid">${field('end','Data do retorno',today(),'date',`min="${t.start}" max="${today()}"`)}${field('endMeter',`Leitura no retorno (${v.unit})`,v.meter,'number',`min="${v.meter}" step="0.1"`)}</div><p class="hint">O veículo volta ao pátio e fica disponível com checklist pendente. Uma nova saída exige a conclusão da conferência.</p>`,'Registrar retorno e conferir'));}
function openChecklist(id){const c=db.checklists.find(c=>c.id===id);assert(c,'Checklist não encontrado.');const v=getVehicle(c.vehicleId),t=db.trips.find(t=>t.id===c.tripId);const logged=sum(db.expenses.filter(e=>e.role==='locatario'&&e.vehicleId===v.id&&e.category==='Combustível'&&e.date>=t.start&&e.date<=t.end),'liters');if(c.done){openDialog('Checklist concluído',`<div class="notice ${c.damage?'warn':''}">${esc(v.plate)} · ${c.damage?'Avaria identificada e encaminhada à oficina':'Integridade validada'}</div>${table(['Conferência','Resultado'],[['Percurso',`${num(c.distance)} ${v.unit}`],['Combustível inicial',`${num(t.startFuel)} L`],['Abastecido',`${num(c.refueled)} L`],['Combustível final',`${num(c.endFuel)} L`],['Consumo validado',`${num(c.consumed)} L`],...['tires','brakes','lights','body','fluids'].map((k,i)=>[['Pneus','Freios','Luzes','Carroceria','Fluidos'][i],statusBadge(c[k])]),['Observações',esc(c.notes)],['Conferido em',dateLabel(c.completed)]])}`);return;}
 openDialog('Checklist de retorno',form('checklist-form',`<input name="id" type="hidden" value="${id}"><div class="notice">${esc(v.plate)} · ${esc(workName(t.workId))}<br>Percurso: <strong>${num(t.endMeter-t.startMeter)} ${v.unit}</strong> · combustível inicial: ${num(t.startFuel)} L</div><fieldset><legend>01 · Conferência de combustível</legend><div class="form-grid">${field('refueled','Total abastecido nesta rotina (L)',logged,'number','min="0" step="0.1"')}${field('endFuel','Combustível restante no retorno (L)',0,'number',`min="0" max="${v.tank}" step="0.1"`)}</div><p class="hint">Consumo = combustível inicial + abastecido − combustível final. Foram localizados ${num(logged)} L em lançamentos do período; confira os comprovantes antes de validar.</p><label class="check-label"><input name="confirmed" type="checkbox" required>Conferi as leituras do medidor e os volumes de combustível.</label></fieldset><fieldset><legend>02 · Integridade do veículo</legend><div class="form-grid">${[['tires','Pneus e rodas'],['brakes','Freios'],['lights','Luzes e sinalização'],['body','Carroceria e acessórios'],['fluids','Motor, fluidos e vazamentos']].map(([key,label])=>select(key,label,[['','Selecione'],['Ok','Em boas condições'],['Avaria','Avaria / requer manutenção']])).join('')}</div><label>Observações e descrição de avarias<textarea name="notes" maxlength="1000" placeholder="Descreva os pontos encontrados. Obrigatório se houver avaria."></textarea></label><p class="hint">Qualquer avaria abre uma solicitação na oficina e muda a condição para “Necessita manutenção”.</p></fieldset>`,'Concluir checklist'));}
function renderWorks(){return head('Obras e motoristas',ui.role==='locador'?'Consulta operacional complementar à gestão da sua frota.':'Organize os canteiros e seus responsáveis.',btn('+ Nova obra','new-work','','primary')+btn('+ Motorista','new-driver'))+`<div class="grid-2">${panel('Canteiros de obra',`${db.works.length} locais cadastrados`,db.works.map(w=>`<div class="list-card"><div><h3>${esc(w.name)}</h3><p>${esc(w.location)}<br>Gestor: ${esc(w.manager)}</p><p>${db.trips.filter(t=>t.workId===w.id&&!t.end).length} veículos em operação</p></div>${statusBadge(w.status)}</div>`).join(''))}${panel('Motoristas responsáveis','Condutores cadastrados por obra',db.drivers.map(d=>`<div class="list-card"><div><h3>${esc(d.name)}</h3><p>CNH ${esc(d.license)} · ${esc(d.phone)}<br>${esc(workName(d.workId))}</p><p>Validade: ${dateLabel(d.expires)}</p></div>${badge(d.expires<today()?'CNH vencida':'CNH válida',d.expires<today()?'red':'green')}</div>`).join(''))}</div>`;}
function renderFinance(){const m=metrics(),receipts=ui.financeTab==='receipts';const invoices=selectedInvoices().filter(i=>inRange(i.due));return head('Financeiro',ui.role==='locador'?'Faturamento, parcelas e recebimentos por veículo.':'Despesas da operação e receitas registradas por veículo.',btn('+ Despesa','new-expense','','primary')+btn('+ Categoria','new-category')+btn('+ Faturamento','new-invoice','','blue')+btn('Clientes','clients'))+filters(true)+`<div class="metric-grid">${metric('Faturado',money(m.billed),'Emissão no período','financeiro')}${metric('Recebido',money(m.received),'Baixas no período','financeiro','good')}${metric('A receber',money(m.due),'Saldo por vencimento','financeiro')}${metric('Vencido',money(m.overdue),'Saldo vencido hoje','financeiro','warn')}</div><div class="chips"><button class="chip ${receipts?'active':''}" data-action="finance-tab" data-id="receipts">Parcelas e recebimentos</button><button class="chip ${!receipts?'active':''}" data-action="finance-tab" data-id="expenses">Despesas por categoria</button></div>${receipts?panel('Agenda de recebimentos','Parcelas com vencimento no período selecionado',`<div class="actions no-print" style="margin-bottom:16px">${['all','Em aberto','Parcial','Vencido','Recebido'].map(s=>`<button class="chip ${ui.invoiceStatus===s?'active':''}" data-action="invoice-status" data-id="${s}">${s==='all'?'Todos os status':s}</button>`).join('')}</div>`+table(['Cliente / veículo','Vencimento','Parcela','Faturado','Recebido','Saldo','Status','Ações'],invoices.sort((a,b)=>a.due.localeCompare(b.due)).map(i=>[`${esc(clientName(i.clientId))}<small>${esc(vehicleName(i.vehicleId))} · ${esc(i.description)}</small>`,dateLabel(i.due),esc(i.installment),money(i.amount),money(paid(i)),money(balance(i)),statusBadge(invoiceStatus(i)),btn('Histórico','invoice-detail',i.id,'small')+(balance(i)>0?btn('Receber','payment',i.id,'small primary'):'')]),[3,4,5])):panel('Despesas registradas',`Total filtrado: ${money(m.expense)}`,table(['Data','Veículo','Categoria','Descrição','Litros','Valor'],selectedExpenses().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>[dateLabel(e.date),esc(vehicleName(e.vehicleId)),esc(e.category),esc(e.description),e.liters?num(e.liters):'—',money(e.amount)]),[4,5]))}`;}
function openExpense(){openDialog('Registrar nova despesa',form('expense-form',`<p class="hint">O lançamento pertence à visão atual: ${ui.role==='locador'?'locador':'locatário'}.</p><div class="form-grid">${select('vehicleId','Veículo',db.vehicles.map(v=>[v.id,v.plate]))}${select('category','Categoria',db.categories.map(c=>[c,c]))}${field('amount','Valor total (R$)','','number','min="0.01" step="0.01"')}${field('date','Data da despesa',today(),'date')}${field('liters','Litros abastecidos (se combustível)',0,'number','min="0" step="0.1"')}${select('workId','Obra / centro de custo',[['','Sem obra'],...db.works.map(w=>[w.id,w.name])])}</div><label>Descrição<textarea name="description" maxlength="500" placeholder="Ex.: abastecimento no posto da rodovia" required></textarea></label><p class="hint">Uma despesa de manutenção deve ser lançada aqui para compor os gastos. Estimativas da oficina não são somadas automaticamente.</p>`,'Registrar despesa'));$('[name="workId"]').required=false;updateLiters();}
function updateLiters(){const c=$('[name="category"]'),l=$('[name="liters"]');if(c&&l){l.disabled=c.value!=='Combustível';l.required=!l.disabled;l.min=l.disabled?'0':'0.1';if(l.disabled)l.value=0;}}
function openInvoice(){assert(db.clients.length,'Cadastre um cliente antes de faturar.');openDialog('Faturar e agendar recebimentos',form('invoice-form',`<div class="notice">O total será dividido em parcelas. O faturamento considera a data de emissão; receber uma parcela não fatura novamente.</div><div class="form-grid">${select('clientId','Cliente',db.clients.map(c=>[c.id,c.name]))}${select('vehicleId','Veículo faturado',db.vehicles.map(v=>[v.id,v.plate]))}${field('amount','Valor total a faturar (R$)','','number','min="0.01" step="0.01"')}${field('count','Quantidade de parcelas mensais',1,'number','min="1" max="36" step="1"')}${field('issued','Data da emissão',today(),'date')}${field('due','Primeiro vencimento',today(),'date')}${ui.role==='locatario'?select('workId','Obra relacionada',[['','Sem obra'],...db.works.map(w=>[w.id,w.name])]):''}</div>${field('description','Descrição / referência','','text','maxlength="150" placeholder="Ex.: locação novembro / medição"')}`,'Gerar faturamento'));const w=$('[name="workId"]');if(w)w.required=false;}
function openPayment(id){const i=db.invoices.find(i=>i.id===id);assert(i&&balance(i)>0,'Esta parcela já foi recebida.');openDialog('Registrar recebimento',form('payment-form',`<input name="id" type="hidden" value="${id}"><div class="notice">${esc(clientName(i.clientId))} · ${esc(vehicleName(i.vehicleId))}<br>Saldo da parcela: <strong>${money(balance(i))}</strong></div><div class="form-grid">${field('amount','Valor recebido (R$)',balance(i)/100,'number',`min="0.01" max="${balance(i)/100}" step="0.01"`)}${field('date','Data do recebimento',today(),'date',`min="${i.issued}" max="${today()}"`)}</div><p class="hint">Baixas parciais mantêm o restante em aberto. A baixa integral quita a parcela.</p>`,'Confirmar recebimento'));}
function openInvoiceDetail(id){const i=db.invoices.find(i=>i.id===id);openDialog('Histórico da parcela',`<div class="notice">${esc(clientName(i.clientId))} · ${esc(i.description)}<br>Emissão: ${dateLabel(i.issued)} · vencimento: ${dateLabel(i.due)}<br>Faturado: ${money(i.amount)} · saldo: ${money(balance(i))}</div>${table(['Data da baixa','Valor recebido'],i.payments.map(p=>[dateLabel(p.date),money(p.amount)]),[1])}`);}
function openClients(){openDialog('Clientes',`<div class="actions" style="margin-bottom:20px">${btn('+ Cadastrar cliente','new-client','','primary')}</div>${table(['Cliente','Documento','Contato'],db.clients.map(c=>[esc(c.name),esc(c.document||'—'),esc(c.contact)]))}`);}
function maintenanceTable(list){return table(['Veículo / serviço','Data','Estimativa / custo','Status','Ação'],list.map(m=>[`${esc(vehicleName(m.vehicleId))}<small>${esc(m.type)} · ${esc(m.description)}</small>`,dateLabel(m.date),money(m.cost),statusBadge(m.status),m.status!=='Concluída'?btn('Concluir serviço','finish-maintenance',m.id,'small'):`${dateLabel(m.finished||m.date)}${m.oil?'<small>Óleo atualizado</small>':''}`]),[2]);}
function renderMaintenance(){return head('Oficina e manutenções','Da prevenção ao reparo: acompanhe os serviços da frota.',btn('+ Registrar manutenção','new-maintenance','','primary'))+panel('Ordens de manutenção','Estimativas da oficina não são despesas financeiras automáticas.',maintenanceTable(db.maintenance))+`<div class="section-gap">${panel('Próximas trocas de óleo','Conclua um serviço com troca de óleo para atualizar a leitura de referência.',oilList())}</div>`;}
function openMaintenance(){openDialog('Registrar manutenção',form('maintenance-form',`<div class="form-grid">${select('vehicleId','Veículo',db.vehicles.map(v=>[v.id,v.plate]))}${select('type','Tipo de serviço',[['Preventiva','Preventiva'],['Corretiva','Corretiva'],['Revisão periódica','Revisão periódica']])}${field('date','Data do serviço / agendamento',today(),'date')}${field('cost','Custo estimado (R$)',0,'number','min="0" step="0.01"')}${select('status','Situação',[['Agendada','Agendada'],['Em andamento','Em andamento'],['Pendente','Pendente']])}</div><label>Descrição do serviço<textarea name="description" required maxlength="1000"></textarea></label><p class="hint">A conclusão do serviço permite registrar a leitura e confirmar se houve troca de óleo.</p>`));}
function openFinishMaintenance(id){const m=db.maintenance.find(x=>x.id===id),v=getVehicle(m.vehicleId);openDialog('Concluir serviço',form('finish-maintenance-form',`<input name="id" type="hidden" value="${id}"><div class="notice">${esc(v.plate)} · ${esc(m.description)}</div><div class="form-grid">${field('date','Data da conclusão',today(),'date',`min="${m.date}" max="${today()}"`)}${field('meter',`Leitura atual (${v.unit})`,v.meter,'number',`min="${v.meter}" step="0.1"`)}${field('cost','Custo final do serviço (R$)',m.cost/100,'number','min="0" step="0.01"')}</div><label class="check-label"><input name="oil" type="checkbox">Foi realizada a troca de óleo nesta leitura.</label><p class="hint">O veículo será liberado quando não houver outra manutenção pendente ou em andamento. Registre o gasto no financeiro para contabilizá-lo.</p>`,'Concluir e atualizar veículo'));}
function renderDocuments(){return head('Canhotos e documentos','Registre entregas, devoluções, comprovantes e vistorias.',btn('+ Anexar documento','new-document','','primary'))+`<div class="grid-2">${panel('Comprovantes registrados','Arquivos armazenados somente neste navegador',db.documents.map(d=>`<div class="list-card"><div><h3>${esc(d.type)}</h3><p>${esc(vehicleName(d.vehicleId))} · ${dateLabel(d.date)}<br>${esc(d.notes)}</p>${d.name?`<p>${esc(d.name)}</p>`:''}</div>${d.data?btn('Baixar','download-document',d.id,'small'):badge(d.status,'green')}</div>`).join('')||empty())}${panel('Regularidade da documentação','Status calculado pela data de vencimento',db.regulations.map(d=>`<div class="oil-row"><div><strong>${esc(d.title)} · ${esc(vehicleName(d.vehicleId))}</strong><p>Vencimento: ${dateLabel(d.due)}</p></div>${statusBadge(d.due<today()?'Vencido':'Ok')}</div>`).join(''))}</div><div class="section-gap">${panel('Checklists das rotinas','Todos os retornos, pendentes e concluídos',table(['Veículo','Retorno','Status','Conferência'],db.checklists.map(c=>[esc(vehicleName(c.vehicleId)),dateLabel(c.date),statusBadge(c.done?c.damage?'Avaria':'Ok':'Pendente'),btn(c.done?'Ver checklist':'Preencher','checklist',c.id,'small')])))} </div>`;}
function openDocument(){attachmentDraft=null;openDialog('Anexar canhoto ou comprovante',form('document-form',`<div class="form-grid">${select('vehicleId','Veículo',db.vehicles.map(v=>[v.id,v.plate]))}${select('type','Tipo de documento',[['Entrega na obra','Entrega na obra'],['Devolução','Devolução'],['Checklist de inspeção','Checklist de inspeção'],['Comprovante de manutenção','Comprovante de manutenção']])}</div><label class="upload">Selecionar foto ou PDF<input type="file" id="document-file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label><p class="hint" id="attachment-name">Até 1 MB por arquivo nesta demonstração local.</p><label>Observações<textarea name="notes" maxlength="1000"></textarea></label>`,'Salvar documento'));}
const reportTypes={vehicle:'Gastos e faturamento por veículo',monthly:'Faturamento mensal',category:'Despesas por categoria',oil:'Troca de óleo',available:'Veículos disponíveis',checklists:'Checklists de retorno',pending:'Checklists pendentes',invoices:'Faturamentos e parcelas',payments:'Recebimentos realizados',overdue:'Parcelas vencidas',expenses:'Despesas detalhadas'};
// Relatório retorna dados crus: tabela, CSV e impressão usam a mesma seleção.
function reportData(){let headers=[],rows=[],note='';const inv=selectedInvoices();switch(ui.report){
 case 'vehicle':headers=['Veículo','Faturado (R$)','Gastos (R$)','Resultado (R$)'];rows=financialRows().map(r=>[r.label,(r.billed/100).toFixed(2),(r.expense/100).toFixed(2),(r.result/100).toFixed(2)]);break;
 case 'monthly':headers=['Mês','Faturado (R$)'];rows=monthlyRows().map(r=>[r.label,(r.value/100).toFixed(2)]);break;
 case 'category':headers=['Categoria','Gastos (R$)'];rows=categoryRows().map(r=>[r.label,(r.value/100).toFixed(2)]);break;
 case 'oil':headers=['Veículo','Leitura atual','Última troca','Próxima troca','Restantes','Unidade'];rows=oilRows().map(v=>[v.plate,v.meter,v.lastOil,oil(v).next,oil(v).left,v.unit]);note='Fotografia atual da frota; as datas não alteram os medidores.';break;
 case 'available':headers=['Veículo','Modelo','Categoria','Situação','Checklist'];rows=selectedVehicles().filter(v=>vehicleStatus(v)==='Disponível').map(v=>[v.plate,v.model,v.category,'Disponível',pendingCheck(v.id)?'Pendente · nova saída bloqueada':'Em dia']);note='Disponibilidade atual, independente do período.';break;
 case 'pending':case 'checklists':headers=['Veículo','Obra','Retorno','Situação','Percurso','Unidade','Consumo (L)','Integridade'];rows=db.checklists.filter(c=>(ui.report!=='pending'||!c.done)&&inRange(c.date)&&selectedVehicles().some(v=>v.id===c.vehicleId)&&(ui.work==='all'||db.trips.find(t=>t.id===c.tripId)?.workId===ui.work)).map(c=>{const t=db.trips.find(t=>t.id===c.tripId);return [vehicleName(c.vehicleId),workName(t.workId),dateLabel(c.date),c.done?'Concluído':'Pendente',c.done?c.distance:'',getVehicle(c.vehicleId).unit,c.done?c.consumed:'',c.done?c.damage?'Avaria':'Ok':'A conferir'];});break;
 case 'payments':headers=['Cliente','Veículo','Parcela','Recebido em','Valor (R$)'];rows=inv.flatMap(i=>i.payments.filter(p=>inRange(p.date)).map(p=>[clientName(i.clientId),vehicleName(i.vehicleId),i.installment,dateLabel(p.date),(p.amount/100).toFixed(2)]));break;
 case 'overdue':case 'invoices':headers=['Cliente','Veículo','Descrição','Emissão','Vencimento','Parcela','Faturado (R$)','Recebido (R$)','Saldo (R$)','Status'];rows=inv.filter(i=>inRange(i.due)&&(ui.report!=='overdue'||invoiceStatus(i)==='Vencido')).sort((a,b)=>a.due.localeCompare(b.due)).map(i=>[clientName(i.clientId),vehicleName(i.vehicleId),i.description,dateLabel(i.issued),dateLabel(i.due),i.installment,(i.amount/100).toFixed(2),(paid(i)/100).toFixed(2),(balance(i)/100).toFixed(2),invoiceStatus(i)]);note='Período aplicado ao vencimento das parcelas; saldos atualizados até hoje.';break;
 case 'expenses':headers=['Data','Veículo','Obra','Categoria','Descrição','Litros','Valor (R$)'];rows=selectedExpenses().map(e=>[dateLabel(e.date),vehicleName(e.vehicleId),workName(e.workId),e.category,e.description,e.liters,(e.amount/100).toFixed(2)]);break;
 }return {title:reportTypes[ui.report],headers,rows,note};}
function reportContext(){return `${ui.role==='locador'?'Locador':'Locatário'} · ${dateLabel(ui.from)} a ${dateLabel(ui.to)} · veículo: ${ui.vehicle==='all'?'todos':vehicleName(ui.vehicle)} · categoria de despesa: ${ui.category==='all'?'todas':ui.category} · cliente: ${ui.client==='all'?'todos':clientName(ui.client)} · obra: ${ui.work==='all'?'todas':workName(ui.work)} · status: ${ui.invoiceStatus==='all'?'todos':ui.invoiceStatus}`;}
function renderReports(){const r=reportData();let chart='';if(ui.report==='vehicle')chart=vehicleChart(financialRows());if(ui.report==='monthly')chart=lineChart(monthlyRows());if(ui.report==='category')chart=barChart(categoryRows());return head('BI e relatórios','Personalize a análise e leve os resultados com você.',btn('↓ Exportar CSV','export','','primary')+btn('Imprimir / PDF','print'))+`<div class="filters"><label>Relatório<select id="report-type">${Object.entries(reportTypes).map(([k,v])=>opt(k,v,ui.report)).join('')}</select></label><label>Status das parcelas<select id="report-status">${['all','Em aberto','Parcial','Vencido','Recebido'].map(s=>opt(s,s==='all'?'Todos':s,ui.invoiceStatus)).join('')}</select></label></div>`+filters(true)+`<p class="print-title">${esc(reportContext())}</p>${chart?`<div style="margin-bottom:20px">${panel(r.title,'Dados correspondentes aos filtros aplicados',chart)}</div>`:''}${panel(r.title,`${r.rows.length} registros · ${r.note||'Período e filtros aplicados à tabela e à exportação.'}`,table(r.headers,r.rows.map(row=>row.map(esc))))}<p class="hint">CSV compatível com planilhas, com separador “;”. Use “Imprimir / PDF” para salvar a versão de impressão pelo navegador.</p>`;}
function csvCell(value){let s=String(value??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportReport(){const r=reportData();const rows=[[r.title],[reportContext()],[],r.headers,...r.rows];download(new Blob(['\ufeff'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),`avl-${ui.report}-${today()}.csv`);toast('Relatório CSV gerado com os filtros aplicados.');}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const navItems=[['dashboard','Painel'],['veiculos','Veículos'],['obras','Obras'],['financeiro','Financeiro'],['manutencao','Oficina'],['documentos','Canhotos'],['relatorios','Relatórios']];
function render(){const nav=navItems.map(([id,label])=>`<button class="nav-link ${ui.tab===id||(ui.tab==='detail'&&id==='veiculos')?'active':''}" ${ui.tab===id?'aria-current="page"':''} data-action="nav" data-id="${id}">${icon(id)}<span>${label}</span></button>`).join('');$('#desktop-nav').innerHTML=nav;$('#mobile-nav').innerHTML=nav;$('#context-label').textContent=ui.role==='locador'?'Visão do locador':'Visão do locatário';$('#profile').value=ui.role;$('#alert-count').textContent=db.checklists.filter(c=>!c.done).length+db.vehicles.filter(v=>oil(v).left<=0).length;const views={dashboard:renderDashboard,veiculos:renderVehicles,detail:renderDetail,obras:renderWorks,financeiro:renderFinance,manutencao:renderMaintenance,documentos:renderDocuments,relatorios:renderReports};$('#main-content').innerHTML=(views[ui.tab]||renderDashboard)();}
function navigate(tab){ui.tab=tab;if(tab!=='detail'){ui.vehicle='all';ui.category='all';ui.client='all';ui.work='all';ui.invoiceStatus='all';}render();window.scrollTo({top:0,behavior:'instant'});$('#main-content').focus({preventScroll:true});}
function openDialog(title,content){formGeneration++;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=content;const d=$('#dialog');if(!d.open)d.showModal();document.body.style.overflow='hidden';}
function closeDialog(){formGeneration++;$('#dialog').close();document.body.style.overflow='';}
$('#dialog').addEventListener('close',()=>{document.body.style.overflow='';});
function toast(message){const el=document.createElement('div');el.className='toast';el.textContent=message;$('#toasts').appendChild(el);setTimeout(()=>el.remove(),5000);}
function formError(error){const el=$('#dialog').open?$('#form-error'):null;if(el){el.hidden=false;el.textContent=error.message||String(error);el.scrollIntoView({block:'nearest'});}else toast(error.message||String(error));}
function commit(change,message,after){Repo.transact(change);closeDialog();render();if(message)toast(message);if(after)after();}
function clearFilters(){Object.assign(ui,{from:monthDate(0,1),to:monthDate(0,31),vehicle:'all',category:'all',client:'all',work:'all',invoiceStatus:'all'});render();}
async function readFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file);});}
async function resizePhoto(file){assert(['image/jpeg','image/png','image/webp'].includes(file.type),'Use imagens JPG, PNG ou WebP.');assert(file.size<=8*1024*1024,'Cada foto deve ter até 8 MB.');const url=await readFile(file);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Imagem inválida.'));img.src=url;});const scale=Math.min(1,1200/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.72);}
document.addEventListener('change',async e=>{try{
 if(e.target.id==='profile'){ui.role=e.target.value;ui.status='Todos';ui.financeTab=ui.role==='locador'?'receipts':'expenses';clearFilters();return;}
 if(e.target.id==='report-type'){ui.report=e.target.value;render();return;}
 if(e.target.id==='report-status'){ui.invoiceStatus=e.target.value;render();return;}
 if(e.target.name==='category')updateLiters();
 if(e.target.id==='vehicle-images'){const files=[...e.target.files];assert(photosDraft.length+files.length<=4,'Use no máximo quatro fotos por veículo.');photoBusy=true;const generation=formGeneration;const submit=$('#vehicle-form [type="submit"]');submit.disabled=true;try{const loaded=await Promise.all(files.map(resizePhoto));if(generation===formGeneration){photosDraft.push(...loaded);if($('#photo-draft'))renderPhotoDraft();}}finally{photoBusy=false;if(submit)submit.disabled=false;e.target.value='';}}
 if(e.target.id==='document-file'){attachmentDraft=null;const file=e.target.files[0];if(!file)return;assert(['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type),'Selecione uma imagem ou PDF.');assert(file.size<=1024*1024,'O limite do protótipo é 1 MB por anexo.');const generation=formGeneration;const data=await readFile(file);if(generation===formGeneration){attachmentDraft={name:file.name,data};$('#attachment-name').textContent=`Selecionado: ${file.name}`;}}
 }catch(error){if(e.target.type==='file')e.target.value='';formError(error);}});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const {action,id}=target.dataset;try{switch(action){
 case 'login-role':ui.role=id;$$('[data-action="login-role"]').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));break;
 case 'logout':$('#app').hidden=true;$('#login-screen').hidden=false;break;
 case 'nav':navigate(id);break;
 case 'close-dialog':closeDialog();break;
 case 'vehicle-filter':ui.status=id;render();break;
 case 'detail':ui.vehicleId=id;ui.vehicle='all';navigate('detail');break;
 case 'edit-vehicle':openVehicle(id);break;
 case 'allocate':openAllocation(id);break;
 case 'return':openReturn(id);break;
 case 'checklist':openChecklist(id);break;
 case 'photo-main':{const index=Number(id);const p=photosDraft.splice(index,1)[0];photosDraft.unshift(p);renderPhotoDraft();break;}
 case 'photo-remove':photosDraft.splice(Number(id),1);renderPhotoDraft();break;
 case 'clear-filters':clearFilters();break;
 case 'six-months':ui.from=monthDate(-5,1);ui.to=monthDate(0,31);render();break;
 case 'report':ui.report=id;navigate('relatorios');break;
 case 'finance-tab':ui.financeTab=id;render();break;
 case 'invoice-status':ui.invoiceStatus=id;render();break;
 case 'new-expense':openExpense();break;
 case 'new-category':openDialog('Nova categoria financeira',form('category-form',field('name','Nome da categoria','','text','maxlength="60" placeholder="Ex.: lavagem, estacionamento"')));break;
 case 'new-invoice':openInvoice();break;
 case 'payment':openPayment(id);break;
 case 'invoice-detail':openInvoiceDetail(id);break;
 case 'clients':openClients();break;
 case 'new-client':openDialog('Cadastrar cliente',form('client-form',field('name','Nome / razão social','','text','maxlength="120"')+field('document','Documento ou identificação','','text','maxlength="30"')+field('contact','E-mail ou telefone de contato','','text','maxlength="100"')));break;
 case 'new-work':openDialog('Cadastrar obra',form('work-form',field('name','Nome da obra','','text','maxlength="100"')+field('location','Cidade / localização','','text','maxlength="150"')+field('manager','Gestor responsável','','text','maxlength="100"')+select('status','Situação',[['Ativa','Ativa'],['Em início','Em início'],['Concluída','Concluída']])));break;
 case 'new-driver':openDialog('Cadastrar motorista',form('driver-form',field('name','Nome completo','','text','maxlength="100"')+`<div class="form-grid">${select('license','Categoria da CNH',[['B','B'],['C','C'],['D','D'],['E','E']])}${field('expires','Validade da CNH','','date')}${select('workId','Obra de referência',db.works.map(w=>[w.id,w.name]))}${field('phone','Telefone','','text','maxlength="30"')}</div>`));break;
 case 'new-maintenance':openMaintenance();break;
 case 'finish-maintenance':openFinishMaintenance(id);break;
 case 'new-document':openDocument();break;
 case 'download-document':{const d=db.documents.find(d=>d.id===id);fetch(d.data).then(r=>r.blob()).then(b=>download(b,d.name));break;}
 case 'export':exportReport();break;
 case 'print':window.print();break;
 case 'notifications':openDialog('Alertas da operação',`<h3>Trocas de óleo</h3>${db.vehicles.filter(v=>oil(v).left<=v.oilInterval*.15).map(v=>`<div class="oil-row"><div><strong>${esc(v.plate)}</strong><p>${num(oil(v).left)} ${v.unit} para a troca</p></div>${statusBadge(oil(v).left<=0?'Vencido':'Atenção')}</div>`).join('')||empty('Nenhuma troca próxima.')}<h3 class="section-gap">Checklists pendentes</h3>${db.checklists.filter(c=>!c.done).map(c=>`<div class="oil-row"><strong>${esc(vehicleName(c.vehicleId))}</strong>${btn('Conferir','checklist',c.id,'small')}</div>`).join('')||empty('Nenhum checklist pendente.')}`);break;
 }}catch(error){formError(error);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f));for(const k of Object.keys(values))if(typeof values[k]==='string')values[k]=values[k].trim();const n=k=>Number(values[k]);try{switch(f.id){
 case 'login-form':$('#login-screen').hidden=true;$('#app').hidden=false;ui.financeTab=ui.role==='locador'?'receipts':'expenses';render();if(loadWarning)toast(loadWarning);break;
 case 'filters':assert(values.from<=values.to,'A data inicial deve ser anterior à final.');assert(Number(values.to.slice(0,4))-Number(values.from.slice(0,4))<10,'Selecione um período de até 10 anos.');Object.assign(ui,values);render();break;
 case 'search-form':ui.search=values.search;render();break;
 case 'vehicle-form':{assert(!photoBusy,'Aguarde o processamento das fotos.');assert(values.model&&values.plate,'Preencha modelo e identificação.');assert(!db.vehicles.some(v=>v.id!==values.id&&v.plate.replace(/\W/g,'').toUpperCase()===values.plate.replace(/\W/g,'').toUpperCase()),'Já existe um veículo com essa identificação.');const old=getVehicle(values.id);assert(n('lastOil')<=n('meter'),'A última troca não pode superar a leitura atual.');assert(!old||n('meter')>=old.meter,'A leitura atual não pode diminuir.');assert(!old||old.unit===values.unit||!db.trips.some(t=>t.vehicleId===old.id),'Não altere a unidade de um veículo com histórico de rotinas.');assert(!(values.status==='Disponível'&&db.maintenance.some(m=>m.vehicleId===values.id&&['Pendente','Em andamento'].includes(m.status))),'Conclua os serviços pendentes na oficina antes de liberar o veículo.');const v={id:values.id||uid(),model:values.model,plate:values.plate.toUpperCase(),category:values.category,year:n('year'),meter:n('meter'),unit:values.unit,lastOil:n('lastOil'),oilInterval:n('oilInterval'),monthly:cents(values.monthly),status:values.status,clientId:values.clientId||'',photos:[...photosDraft],tank:n('tank')};commit(data=>{const index=data.vehicles.findIndex(x=>x.id===v.id);if(index<0)data.vehicles.push(v);else data.vehicles[index]=v;},'Veículo salvo com sucesso.');break;}
 case 'allocation-form':commit(data=>Domain.allocate(data,values.id,{workId:values.workId,driverId:values.driverId,start:values.start,startMeter:n('startMeter'),startFuel:n('startFuel')}),'Veículo alocado à obra.');break;
 case 'return-form':{const id=values.id;commit(data=>Domain.returnTrip(data,id,{end:values.end,endMeter:n('endMeter')}),'Retorno registrado.',()=>openChecklist(pendingCheck(id).id));break;}
 case 'checklist-form':commit(data=>Domain.checklist(data,values.id,{refueled:n('refueled'),endFuel:n('endFuel'),confirmed:values.confirmed==='on',tires:values.tires,brakes:values.brakes,lights:values.lights,body:values.body,fluids:values.fluids,notes:values.notes}),'Checklist salvo e condição do veículo atualizada.');break;
 case 'category-form':assert(values.name,'Informe o nome da categoria.');assert(!db.categories.some(c=>c.toLowerCase()===values.name.toLowerCase()),'Esta categoria já existe.');commit(data=>data.categories.push(values.name),'Categoria cadastrada.');break;
 case 'expense-form':{const v=getVehicle(values.vehicleId);assert(v,'Selecione um veículo.');assert(values.category!=='Combustível'||n('liters')>0,'Informe a quantidade abastecida.');commit(data=>data.expenses.unshift({id:uid(),role:ui.role,vehicleId:v.id,clientId:v.clientId,category:values.category,amount:cents(values.amount),date:values.date,liters:values.category==='Combustível'?n('liters'):0,description:values.description,workId:values.workId||activeTrip(v.id)?.workId||''}),'Despesa registrada.');break;}
 case 'client-form':assert(values.name,'Informe o cliente.');commit(data=>data.clients.push({id:uid(),...values}),'Cliente cadastrado.');break;
 case 'invoice-form':{const total=cents(values.amount),count=n('count');assert(Number.isInteger(count)&&count>=1&&count<=36,'Use de 1 a 36 parcelas.');assert(total>=count,'Cada parcela deve ter pelo menos R$ 0,01.');assert(values.due>=values.issued,'O vencimento não pode anteceder a emissão.');const group=uid();commit(data=>{for(let i=0;i<count;i++)data.invoices.push({id:uid(),group,role:ui.role,vehicleId:values.vehicleId,clientId:values.clientId,workId:values.workId||'',issued:values.issued,due:addMonths(values.due,i),description:values.description,amount:Math.floor(total/count)+(i<total%count?1:0),installment:`${i+1}/${count}`,payments:[]});},`${count} parcela(s) gerada(s) com total de ${money(total)}.`);break;}
 case 'payment-form':commit(data=>Domain.payment(data,values.id,{date:values.date,amount:cents(values.amount)}),'Recebimento registrado.');break;
 case 'work-form':commit(data=>data.works.push({id:uid(),...values}),'Obra cadastrada.');break;
 case 'driver-form':commit(data=>data.drivers.push({id:uid(),...values}),'Motorista cadastrado.');break;
 case 'maintenance-form':commit(data=>{data.maintenance.unshift({id:uid(),vehicleId:values.vehicleId,type:values.type,date:values.date,cost:cents(values.cost),status:values.status,description:values.description,oil:false});if(['Pendente','Em andamento'].includes(values.status))data.vehicles.find(v=>v.id===values.vehicleId).status=values.status==='Pendente'?'Necessita manutenção':'Manutenção';},'Manutenção registrada.');break;
 case 'finish-maintenance-form':commit(data=>Domain.finishMaintenance(data,values.id,{date:values.date,meter:n('meter'),cost:cents(values.cost),oil:values.oil==='on'}),'Manutenção concluída.');break;
 case 'document-form':assert(attachmentDraft,'Selecione um arquivo e aguarde a leitura.');commit(data=>data.documents.unshift({id:uid(),vehicleId:values.vehicleId,type:values.type,notes:values.notes,date:today(),status:'Registrado',...attachmentDraft}),'Documento salvo.');break;
 }}catch(error){formError(error);}});
